// Verus program to count distinct non-square rectangles with perimeter n.
//
// We count pairs (a,b) with positive integers, a < b, and 2a + 2b = n.
// If n is odd, result = 0.
// If n even and n % 4 == 2, result = n / 4.
// If n divisible by 4, result = n / 4 - 1.
//
// This matches the problem statement properties.
//
// Note: n > 0 as stated in problem.

verus!{

fn solve(n: i8) -> (result: i8)
    ensures
        // If n is odd, result is 0
        (n % 2 != 0) ==> (result == 0) &&

        // If n % 4 == 2, result = n / 4
        ((n % 4 == 2)) ==> (result == n / 4) &&

        // If n % 4 == 0, result = n / 4 - 1
        ((n % 4 == 0)) ==> (result == n / 4 - 1) &&

        // Result is never negative
        0 <= result
{
    // If n is odd, no pairs possible.
    if n % 2 != 0 {
        return 0;
    }

    // Now n is even.
    // Define half = n / 2
    let half = n / 2;

    if n % 4 == 2 {
        // For n % 4 == 2, result = n / 4
        return n / 4;
    } else {
        // n % 4 == 0:
        // Count pairs (a,b): a<b, a + b = half
        // The number of positive integer pairs (a,b) with a < b and a + b = half
        // is half/2 - 1 (because a,b positive and a < b)
        // This equals n/4 - 1
        return n / 4 - 1;
    }
}

}